from robot.libraries.BuiltIn import BuiltIn
from robot.running.statusreporter import StatusReporter
from robot.result import Keyword as KeywordResult
from robot.running.model import Keyword
from robot.output import LOGGER

from robot.result import For as ForResult
from robot.result import ForIteration as ForIterationResult
from robot.running.model import For as ForData


def _disable_cached_logs():
    """
    Disable Robot Framework log caching.

    Robot Framework may cache log messages internally. In some versions/configurations
    this interacts badly with keyword timeouts (the ``timeout`` feature/tag), causing
    missing or delayed log output. This helper forces ``no_cache=True`` when calling
    the underlying ``LOGGER._log_message`` implementation, but only when timeouts are
    active.

    Note:
        This function intentionally touches Robot Framework internals
        (``LOGGER._log_message`` and ``BuiltIn()._context``).
    """
    old_logs_message = LOGGER._log_message
    if BuiltIn()._context.timeouts and "Logger" in str(old_logs_message):
        def new_logs_message(msg, no_cache=False):
            old_logs_message(msg, no_cache=True)

        LOGGER._log_message = new_logs_message


class RobotWrapper(object):

    def __init__(self, wrap_name, wrap_type):
        """
        :author: jakub.siluch@nokia.com
        :maintainer: jakub.siluch@nokia.com
        :note: Please contact with maintainer with any issue of this KW(prototype version)

        A small helper for creating nested Robot Framework execution/reporting levels.

        This wrapper uses Robot Framework's ``StatusReporter`` with the appropriate
        data/result objects so you can emit keyword/for-loop structures (including
        nested "FOR" + "ITERATION") programmatically.

        It also contains compatibility shims for differences between Robot Framework
        versions (notably RF 5.0 vs RF 7.0).

        Args:
            wrap_name: Name of the first/top level entry (keyword name or for-loop flavor).
            wrap_type: Type of the first/top level entry. Supported values:
                - ``"kw"``: keyword level (treated as keyword for legacy compatibility)
                - ``"for"``: for-loop level
                - ``"foritem"``: for-loop iteration ("FOR item") level

        Raises:
            ValueError: If only one of ``wrap_name`` / ``wrap_type`` is provided.

        Example:
            Creating a Robot Framework "FOR" loop structure:

            with RobotWrapper(wrap_name="FOR LOOP", wrap_type="for") as wrapper:
                for iteration in range(10):
                    wrapper.create_level(
                        "VAR={}".format(iteration), wrap_type="foritem", level=2
                    )
                    robot_kw(log_info_to_console, msg=iteration)
        """
        _disable_cached_logs()
        self.context = BuiltIn()._context
        self.levels = {}
        if wrap_name is None and wrap_type is None:
            return
        if wrap_name is None or wrap_type is None:
            raise ValueError("Provide both wrap_name and wrap_type, or neither (manual mode).")

        self._create_first_level(wrap_name=wrap_name, wrap_type=wrap_type)

    @staticmethod
    def create_for_data_and_result(flavor, variables, values):
        """
        Create the ``For`` model/result objects expected by ``StatusReporter``.

        Robot Framework changed constructor argument names between versions.
        This method returns a dict that can be passed directly into ``StatusReporter``.

        Args:
            flavor: For-loop "flavor" string (e.g. 'IN RANGE', 'IN', etc.).
            variables: Variable assignment structure as expected by the RF version.
            values: Values iterable/tuple as expected by the RF version.

        Returns:
            dict: ``{"data": <ForData>, "result": <ForResult>}``
        """
        try:
            data = ForData(variables=variables, flavor=flavor, values=values)
            result = ForResult(variables=variables, flavor=flavor, values=values)
        except TypeError:
            data = ForData(assign=variables, flavor=flavor, values=values)
            result = ForResult(assign=variables, flavor=flavor, values=values)
        return {"data": data, "result": result}

    @staticmethod
    def create_for_item_data_and_result(variables):
        """
        Create the ``ForIteration`` model/result objects expected by ``StatusReporter``.

        Args:
            variables: Either a dict like ``{"${i}": "1"}`` or a legacy string like
                ``"${i}=1"``.

        Returns:
            dict: ``{"data": <ForData>, "result": <ForIterationResult>}``
        """
        if isinstance(variables, str):  # Backward compatibility with legacy input format.
            parts = variables.split("=")
            iteration_variables = {parts[0]: parts[1]} if len(parts) == 2 else {}
        else:
            iteration_variables = variables

        try:  # RF 5.x
            data = ForData(variables=(), flavor="", values=())
            result = ForIterationResult(variables=iteration_variables)
        except TypeError:  # RF 7.x+
            data = ForData(assign=(), flavor="", values=())
            result = ForIterationResult(assign=iteration_variables)

        return {"data": data, "result": result}

    @staticmethod
    def create_keyword_data_and_result(kw_name):
        """
        Create the keyword model/result objects expected by ``StatusReporter``.

        Robot Framework uses different result field names and may require an
        "implementation" object in newer versions.

        Args:
            kw_name: Keyword name shown in Robot Framework logs/reports.

        Returns:
            dict: At minimum ``{"data": <Keyword>, "result": <KeywordResult>}``.
            For newer Robot Framework versions it can also include
            ``{"implementation": <StaticKeyword>}``.
        """
        try:  # RF 5.x
            data = Keyword()
            result = KeywordResult(kwname=kw_name)
            return {"data": data, "result": result}
        except TypeError:  # RF 7.x+
            from robot.running.librarykeyword import StaticKeyword
            data = Keyword()
            result = KeywordResult(name=kw_name)
            implementation = StaticKeyword(method_name=kw_name, owner=None)
            return {"data": data, "result": result, "implementation": implementation}

    def create_for_level(self, flavor, variables=(), values=(), level=None):
        """Enter a new "FOR" level (loop) in Robot Framework reporting."""
        status_reporter_kwargs = self.create_for_data_and_result(flavor=flavor, variables=variables, values=values)
        self._enter_level(level=level, **status_reporter_kwargs)

    def create_for_item_level(self, variables, level=None):
        """Enter a new "FOR ITERATION" level in Robot Framework reporting."""
        status_reporter_kwargs = self.create_for_item_data_and_result(variables=variables)
        self._enter_level(level=level, **status_reporter_kwargs)

    def create_keyword_level(self, kw_name, level=None):
        """Enter a new keyword level in Robot Framework reporting."""
        status_reporter_kwargs = self.create_keyword_data_and_result(kw_name=kw_name)
        self._enter_level(level=level, **status_reporter_kwargs)

    def _create_data_and_result(self, wrap_name, wrap_type):
        """
        Legacy helper to pick the correct ``create_*`` method based on type.

        Note:
            This API exists for backward compatibility. Prefer
            ``create_for_level``, ``create_for_item_level`` and ``create_keyword_level``.
        """
        if wrap_type.lower() == "for":
            return self.create_for_data_and_result(flavor=wrap_name, variables={}, values=())
        elif wrap_type.lower() == "foritem":
            return self.create_for_item_data_and_result(variables=wrap_name)
        else:
            return self.create_keyword_data_and_result(kw_name=wrap_name)

    def _enter_level(self, level, **status_reporter_kwargs):
        """
        Enter a new reporting level and manage the internal level stack.

        This method opens a new ``StatusReporter`` context. If the requested ``level``
        equals the current highest level, the current level is replaced (closed and
        re-opened) to allow reusing the same depth.
        """
        # First/top level.
        if not self.levels:
            creation_level = 1 if level is None else int(level)
            if creation_level != 1:
                raise Exception("Bad level selected to create first level (must be 1).")
            reporter = StatusReporter(context=self.context, **status_reporter_kwargs)
            reporter.__enter__()
            self.levels[1] = reporter
            return

        highest_level = sorted(self.levels)[-1]

        if level is None or int(level) == highest_level + 1:
            creation_level = highest_level + 1
        elif int(level) == highest_level:
            self.levels[highest_level].__exit__(None, None, None)
            del self.levels[highest_level]
            creation_level = highest_level
            highest_level = sorted(self.levels)[-1]  # parent may have changed
        else:
            raise Exception("Bad level selected to create")

        # Attach a parent so RF can correctly structure iterations/else branches/etc.
        parent_result = self.levels[highest_level].result
        result = status_reporter_kwargs.get("result", None)
        if result is not None and getattr(result, "parent", None) is None:
            try:
                result.parent = parent_result
            except Exception:
                pass  # Some result types may not allow parent assignment.

        reporter = StatusReporter(context=self.context, **status_reporter_kwargs)
        reporter.__enter__()
        self.levels[creation_level] = reporter

    def close_level_to(self, level):
        """
        Close all open levels down to (but not including) the requested level.

        Args:
            level: Level number to close down to.
        """
        if level in list(self.levels):
            for actual_level in sorted(self.levels, reverse=True):
                if level == actual_level:
                    break
                self.levels[actual_level].__exit__(None, None, None)
                del self.levels[actual_level]
        else:
            raise Exception("Bad level selected to close")

    def _create_first_level(self, wrap_name, wrap_type):
        """Create the initial/top level reporter entry."""
        status_reporter_kwargs = self._create_data_and_result(wrap_name, wrap_type)
        self._enter_level(level=1, **status_reporter_kwargs)

    def create_level(self, wrap_name, wrap_type, level=None):
        """Legacy public API to create a level based on ``wrap_type``."""
        status_reporter_kwargs = self._create_data_and_result(wrap_name, wrap_type)
        self._enter_level(level=level, **status_reporter_kwargs)

    def __enter__(self):
        """Context-manager entry; returns ``self``."""
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Close all open levels, propagating the exception to the innermost level."""
        sorted_levels = sorted(self.levels, reverse=False)
        try:
            self.levels[sorted_levels[-1]].__exit__(exc_type, exc_val, exc_tb)
        except Exception:
            pass
        finally:
            sorted_levels.remove(sorted_levels[-1])

        for level in sorted_levels:
            try:
                self.levels[level].__exit__(None, None, None)
            except Exception:
                pass
